    rows=[r for r,row in enumerate(grid) if 5 in row]
    cols=[c for c in range(len(grid[0])) if any(grid[r][c]==5 for r in range(len(grid)))]
    top,bottom,left,right=min(rows),max(rows),min(cols),max(cols)
    h=bottom-top+1; w=right-left+1
    # Repeat a 5-border separator after every 4-wide band, starting inside.
    # Each 4x4 cell group is filled with color 2 except boundary lines of 5.
    for r in range(top+1,bottom):
        for c in range(left+1,right):
            if (r-top-1)%4 == 3 or (c-left-1)%4 == 3:
                out[r][c]=5
            else:
